WITH latest AS (SELECT id, store_id, sale_date, units, revenue FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units DESC NULLS LAST, id) AS dedup_rank FROM store_sales) ranked WHERE dedup_rank = 1) SELECT CASE WHEN revenue >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, store_id, CORR(revenue, units) AS corr_revenue_units, MIN(revenue) AS min_revenue, APPROX_PERCENTILE(revenue, 0.95) AS revenue_p95, PERCENT_RANK() OVER (PARTITION BY CASE WHEN revenue >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY APPROX_PERCENTILE(revenue, 0.95) DESC) AS revenue_p95_percent_rank FROM latest GROUP BY CASE WHEN revenue >= 3700 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id ORDER BY min_revenue DESC NULLS FIRST
